    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Investment Casting - Wax pattern tooling$q$, 'process', 'single', false, true, true, $q$The wax pattern die over the lifetime volume: the single cavity mold base cost from the plant's regression on the mold base area and the pattern height (read in square inches and inches), with the tolerance, construction, finishing, cooling line and action allowances; one die makes its shots per tool.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$The wax pattern die over the lifetime volume: the single cavity mold base cost from the plant's regression on the mold base area and the pattern height (read in square inches and inches), with the tolerance, construction, finishing, cooling line and action allowances; one die makes its shots per tool.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
