    (v_id, $q$Height Multiplier$q$, $q$Height Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 13, true),
    (v_id, $q$Tolerance Factor$q$, $q$Tolerance Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 14, true),
