$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Investment Casting - Tree$q$, 16, 0),
    ($q$Investment Casting - Metal per casting$q$, 7, 0),
    ($q$Investment Casting - Material cost$q$, 8, 0),
    ($q$Investment Casting - Wax pattern molding$q$, 24, 1),
    ($q$Investment Casting - Bench: Pattern finishing$q$, 3, 0),
    ($q$Investment Casting - Bench: Tree assembly$q$, 7, 0),
    ($q$Investment Casting - Slurry dipping$q$, 4, 2),
    ($q$Investment Casting - Sand coating$q$, 4, 2),
    ($q$Investment Casting - Robotic assist$q$, 5, 1),
    ($q$Investment Casting - Drying$q$, 5, 1),
    ($q$Investment Casting - Flash fire de-waxing$q$, 14, 1),
    ($q$Investment Casting - Steam autoclave de-waxing$q$, 13, 1),
    ($q$Investment Casting - Bench: Wax vent plugging$q$, 4, 0),
    ($q$Investment Casting - Bench: Mold cleaning$q$, 3, 0),
    ($q$Investment Casting - Bench: Shell inspection$q$, 5, 0),
    ($q$Investment Casting - Mold burnout$q$, 13, 1),
    ($q$Investment Casting - Mold preheating$q$, 13, 1),
    ($q$Investment Casting - Metal pouring$q$, 21, 1),
    ($q$Investment Casting - Cooling$q$, 19, 1),
    ($q$Investment Casting - Knockout$q$, 3, 1),
    ($q$Investment Casting - Band saw cut-off$q$, 3, 1),
    ($q$Investment Casting - Bench: Abrasive wheel cutting$q$, 3, 0),
    ($q$Investment Casting - Belt sanding$q$, 3, 1),
    ($q$Investment Casting - Bench: Abrasive disc grinding$q$, 3, 0),
    ($q$Investment Casting - Bench: Finishing$q$, 6, 0),
    ($q$Investment Casting - Bench: Dimensional inspecting$q$, 3, 0),
    ($q$Investment Casting - Wax pattern tooling$q$, 34, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Casting Investment$q$) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1046: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
